<?php
declare(strict_types=1);
require (getenv('TPK_CONFIG_ROOT')?:dirname(__DIR__)).'/config.php';
if(!in_array('--confirm',$argv,true)){fwrite(STDERR,"Use --confirm after a verified database backup. Provide --source=/protected/path/programme.pdf.\n");exit(1);}
$source=null;foreach($argv as $arg)if(str_starts_with($arg,'--source='))$source=substr($arg,9);
if(!$source||!is_readable($source)||!str_starts_with(file_get_contents($source,false,null,0,5),'%PDF-'))throw new RuntimeException('A readable programme PDF is required.');
$db=db();$campus=(int)(tpk_regular_campus($db)['id']??0);$q=$db->prepare("SELECT id FROM staff_users WHERE campus_id=? AND access_level='TPK_SUPER_ADMIN' AND is_active=1 AND account_status='VERIFIED' ORDER BY id LIMIT 1");$q->execute([$campus]);$admin=(int)$q->fetchColumn();if(!$campus||!$admin)throw new RuntimeException('Active headquarters Super Admin required.');
$slug='rock-solid-teen-boys-2026';$q=$db->prepare('SELECT event_id FROM event_teen_forms WHERE slug=?');$q->execute([$slug]);$existing=$q->fetchColumn();if($existing){echo "Boys Programme already exists: event $existing. No existing records overwritten.\n";exit;}
$q=$db->prepare("SELECT id FROM ministry_events WHERE campus_id=? AND starts_on='2026-10-17' AND name=?");$q->execute([$campus,'Rock Solid 2026: Teen Boys Programme']);if($q->fetchColumn())throw new RuntimeException('Matching event exists without form settings. Review before linking.');
$rules="1. Treat everyone with respect. Listen, take turns and do not bully or use abusive language.\n2. Take part in the sessions and activities, and follow the programme team's safety instructions.\n3. Use devices responsibly and only for the activity requested during teaching sessions.\n4. Never share passwords or private account details. Use digital tools honestly, not to copy work or scam anyone.\n5. Keep programme communication in approved, supervised channels. No private one-to-one chats with adult mentors.\n6. If you are worried, uncomfortable or need help, speak to your parent, guardian or the programme lead.";
$directory=(getenv('TPK_CONFIG_ROOT')?:dirname(__DIR__)).'/storage/event-resources';if(!is_dir($directory)&&!mkdir($directory,0750,true))throw new RuntimeException('Protected event storage unavailable.');
$stored=bin2hex(random_bytes(20)).'.pdf';$path=$directory.'/'.$stored;if(!copy($source,$path))throw new RuntimeException('Could not preserve programme source.');chmod($path,0640);
$db->beginTransaction();try{
 $db->prepare("INSERT INTO ministry_events(campus_id,name,event_type,starts_on,ends_on,registration_opens,registration_closes,countdown_enabled,public_registration,status,description,public_key,created_by,theme_name,timezone) VALUES(?,?,'OTHER','2026-10-17','2026-10-31','2026-10-13','2026-10-16',0,1,'DRAFT',?,?,?,?,'Africa/Lagos')")->execute([$campus,'Rock Solid 2026: Teen Boys Programme','Three Saturdays for boys aged 11–19: 17, 24 and 31 October 2026. The first two sessions are virtual; the final session is an in-person camp. Grow in faith, emotional awareness, wise decision-making, learning, money management and digital skills. Session times and camp venue will be confirmed by the programme team.',bin2hex(random_bytes(24)),$admin,'Rock Solid: Growing Like Jesus']);$id=(int)$db->lastInsertId();
 $db->prepare('INSERT INTO event_teen_forms(event_id,slug,min_age,max_age,rules) VALUES(?,?,11,19,?)')->execute([$id,$slug,$rules]);
 $db->prepare("INSERT INTO event_source_files(event_id,original_name,stored_name,mime_type,byte_size,sha256,uploaded_by) VALUES(?,?,?,'application/pdf',?,?,?)")->execute([$id,'Tribe Petra Teen Boys Programme 2026 (1).pdf',$stored,filesize($path),hash_file('sha256',$path),$admin]);$file=(int)$db->lastInsertId();
 $resources=[
  ['Built on the Rock','2026-10-17',4,5,"# Week 1: Built on the Rock\n\n## Focus\nPersonal fellowship with God, emotional awareness and online safety.\n\n## Teaching\nBible reading, prayer and a simple quiet-time habit. Naming feelings, pausing before reacting and seeking help.\n\n## Digital lab\nStrong passwords, two-factor authentication, privacy settings, scams and digital footprints. Never collect or share participants' passwords.\n\n## Discussion\nWhat emotion is hardest to control, and what usually triggers it? Breakouts must be supervised by at least two adults.\n\n## Weekly activity\nA seven-day devotional and feelings journal. Check one social app's privacy settings and confirm two-factor authentication is enabled. Keep personal reflections out of public registration records."],
  ['Guard Your Mind','2026-10-24',5,6,"# Week 2: Guard Your Mind\n\n## Focus\nWhat we consume, how we think, wise choices and practical study habits.\n\n## Teaching\nDiscuss online content and peer pressure in an age-appropriate way. Introduce STOP: Stop, Think of consequences, list Options, Pick and pray.\n\n## Study habits\nPut the phone away, use short focused study blocks, teach a topic back to a friend and set one academic goal.\n\n## Digital lab\nUse AI to understand topics, check its answers and avoid copying homework. Create a simple group poster in Canva.\n\n## Group discussion\nApply STOP to exam copying, unverified viral claims and going out without parental knowledge.\n\n## Weekly activity\nReview screen time, reflect on one decision using STOP and prepare the group's poster and presentation."],
  ['Rock Solid Camp','2026-10-31',7,8,"# Week 3: Rock Solid Camp\n\n## Focus\nMoney God's way, practical digital creation and applying all six pillars.\n\n## Money skills\nEarn, save, give and spend. Compare needs and wants, practise delayed gratification and defend a team budget using a pretend ₦20,000. Teach contentment, integrity and legitimate earning.\n\n## Digital creation stations\nRotate through design, video and code: finish a poster, make a 60-second reel, or create a first web page or Scratch game.\n\n## Activities\nTeam games, outdoor challenges, group presentations, a supervised question-and-answer session and personal commitments.\n\n## Safety and collection\nThe source proposes a day camp from 8:00 AM to 4:45 PM. Venue and final arrangements need confirmation. Use supervised activities, first-aid support and release participants only to a parent or authorised adult.\n\n## Source status\nThis is a planning outline, not a record of delivered sessions or attendance."],
 ];
 foreach($resources as $i=>[$title,$date,$first,$last,$content]){
  $db->prepare('INSERT INTO event_days(event_id,day_number,label,calendar_date) VALUES(?,?,?,?)')->execute([$id,$i+1,'Saturday '.($i+1),$date]);$day=(int)$db->lastInsertId();
  $db->prepare("INSERT INTO event_curriculum_resources(event_id,title,resource_type,description,content,source_file_id,source_page_start,source_page_end,min_age,max_age,created_by) VALUES(?,?,'LESSON_PLAN',?,?,?,?,?,11,19,?)")->execute([$id,$title,'Planning notes from the supplied programme outline; editable by Super Admins.',$content,$file,$first,$last,$admin]);$rid=(int)$db->lastInsertId();$db->prepare('INSERT INTO event_curriculum_targets(resource_id,day_id) VALUES(?,?)')->execute([$rid,$day]);
 }
 audit($db,$campus,'EVENT_CREATED','Event',$id,['programme'=>$slug,'status'=>'DRAFT','source'=>'User-supplied programme outline']);$db->commit();
 echo "Created draft Boys Programme: event $id; ages 11–19; 3 curriculum resources; protected source PDF. Registration dates and rules require review before publishing.\n";
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
